CREATE TABLE `compliance_governance_requests` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `target_type` text NOT NULL CHECK ( `target_type` IN ('program', 'activity', 'evidence_policy') ), `target_id` text NOT NULL, `action` text NOT NULL CHECK (`action` = 'publish'), `sealed_snapshot` text NOT NULL CHECK (json_valid(`sealed_snapshot`)), `sealed_snapshot_sha256` text NOT NULL CHECK ( length(`sealed_snapshot_sha256`) = 64 AND lower(`sealed_snapshot_sha256`) NOT GLOB '*[^0-9a-f]*' ), `status` text DEFAULT 'pending' NOT NULL CHECK ( `status` IN ('pending', 'approved', 'rejected', 'superseded') ), `request_reason` text NOT NULL CHECK (trim(`request_reason`) <> ''), `requested_by_uid` text NOT NULL CHECK (trim(`requested_by_uid`) <> ''), `requested_at` text NOT NULL, `reviewed_by_uid` text DEFAULT '' NOT NULL, `reviewed_at` text DEFAULT '' NOT NULL, `review_note` text DEFAULT '' NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL, CHECK ( (`status` = 'pending' AND `reviewed_by_uid` = '' AND `reviewed_at` = '' AND `review_note` = '') OR (`status` IN ('approved', 'rejected') AND trim(`reviewed_by_uid`) <> '' AND `reviewed_by_uid` <> `requested_by_uid` AND trim(`reviewed_at`) <> '' AND trim(`review_note`) <> '') OR (`status` = 'superseded' AND `reviewed_by_uid` = '' AND trim(`reviewed_at`) <> '' AND trim(`review_note`) <> '') ) );
CREATE UNIQUE INDEX `compliance_governance_requests_pending_idx` ON `compliance_governance_requests` (`organisation_id`, `target_type`, `target_id`, `action`) WHERE `status` = 'pending';
CREATE INDEX `compliance_governance_requests_org_status_idx` ON `compliance_governance_requests` (`organisation_id`, `status`, `requested_at`, `id`);
CREATE INDEX `compliance_governance_requests_target_idx` ON `compliance_governance_requests` (`organisation_id`, `target_type`, `target_id`, `requested_at`, `id`);
ALTER TABLE `compliance_users` ADD `governance_identity_verified` integer DEFAULT 0 NOT NULL CHECK (`governance_identity_verified` IN (0, 1));
ALTER TABLE `compliance_users` ADD `governance_identity_verified_by_uid` text DEFAULT '' NOT NULL;
ALTER TABLE `compliance_users` ADD `governance_identity_verified_at` text DEFAULT '' NOT NULL;
ALTER TABLE `compliance_users` ADD `governance_identity_verification_basis` text DEFAULT '' NOT NULL CHECK ( (`governance_identity_verified` = 0 AND `governance_identity_verified_by_uid` = '' AND `governance_identity_verified_at` = '' AND `governance_identity_verification_basis` = '') OR (`governance_identity_verified` = 1 AND trim(`governance_identity_verified_by_uid`) <> '' AND `governance_identity_verified_by_uid` <> `firebase_uid` AND trim(`governance_identity_verified_at`) <> '' AND trim(`governance_identity_verification_basis`) <> '') );
CREATE INDEX `compliance_users_org_governance_identity_idx` ON `compliance_users` (`organisation_id`, `governance_identity_verified`, `role`, `status`);
ALTER TABLE `compliance_programs` ADD `publication_request_id` text DEFAULT '' NOT NULL;
ALTER TABLE `compliance_programs` ADD `publication_snapshot_sha256` text DEFAULT '' NOT NULL CHECK ( `publication_snapshot_sha256` = '' OR ( length(`publication_snapshot_sha256`) = 64 AND lower(`publication_snapshot_sha256`) NOT GLOB '*[^0-9a-f]*' ) );
ALTER TABLE `compliance_activity_versions` ADD `publication_request_id` text DEFAULT '' NOT NULL;
ALTER TABLE `compliance_activity_versions` ADD `publication_snapshot_sha256` text DEFAULT '' NOT NULL CHECK ( `publication_snapshot_sha256` = '' OR ( length(`publication_snapshot_sha256`) = 64 AND lower(`publication_snapshot_sha256`) NOT GLOB '*[^0-9a-f]*' ) );
ALTER TABLE `compliance_evidence_policy_versions` ADD `publication_request_id` text DEFAULT '' NOT NULL;
ALTER TABLE `compliance_evidence_policy_versions` ADD `publication_snapshot_sha256` text DEFAULT '' NOT NULL CHECK ( `publication_snapshot_sha256` = '' OR ( length(`publication_snapshot_sha256`) = 64 AND lower(`publication_snapshot_sha256`) NOT GLOB '*[^0-9a-f]*' ) );
ALTER TABLE `compliance_evidence_policy_versions` ADD `content_revision` integer DEFAULT 1 NOT NULL CHECK (`content_revision` > 0);
CREATE UNIQUE INDEX `compliance_case_evidence_active_original_idx` ON `compliance_case_evidence` (`organisation_id`, `case_id`, `requirement_id`, `original_sha256`) WHERE `original_sha256` <> '' AND `status` IN ('received', 'under_review', 'accepted');
